package dev.lowspec.rendercore.aether;
import org.junit.jupiter.api.Test; import static org.junit.jupiter.api.Assertions.*;
class AetherPlayerGeometryDrawPlanTest {
 private static AetherPlayerBatchPlan sourcePlan(){AetherGroupIndex<String> groups=new AetherGroupIndex<>(5);groups.build(new String[]{"skin-a","skin-b","skin-a","skin-b","skin-c"},5);AetherPlayerBatchPlan p=new AetherPlayerBatchPlan(5);p.build(groups,new int[]{0,0,0,0,AetherPlayerRenderQueue.SNEAKING},5);return p;}
 @Test void createsStableSkinGroupedRangesAndSkipsMissingGeometry(){AetherPlayerGeometryDrawPlan p=new AetherPlayerGeometryDrawPlan(5);p.build(sourcePlan(),new int[]{0,-1,288,576,-1},new int[]{288,0,288,144,0},new int[]{36,0,36,18,0},5);assertEquals(2,p.batchCount());assertEquals(3,p.packetCount());assertEquals(1,p.missingGeometryCount());assertEquals(0,p.rejectedRangeCount());assertEquals(0,p.batchSkinGroup(0));assertEquals(2,p.batchSize(0));assertEquals(0,p.packetPlayer(0,0));assertEquals(0,p.firstVertex(0,0));assertEquals(36,p.vertexCount(0,0));assertEquals(2,p.packetPlayer(0,1));assertEquals(36,p.firstVertex(0,1));assertEquals(1,p.batchSkinGroup(1));assertEquals(3,p.packetPlayer(1,0));assertEquals(72,p.firstVertex(1,0));assertEquals(18,p.vertexCount(1,0));}
 @Test void rejectsMisalignedOrInconsistentRanges(){AetherPlayerGeometryDrawPlan p=new AetherPlayerGeometryDrawPlan(5);p.build(sourcePlan(),new int[]{1,288,576,864,-1},new int[]{288,287,288,144,0},new int[]{36,36,35,17,0},5);assertEquals(0,p.packetCount());assertEquals(4,p.rejectedRangeCount());}
 @Test void clearsOldFrameAndRejectsInvalidInputs(){AetherPlayerGeometryDrawPlan p=new AetherPlayerGeometryDrawPlan(5);AetherPlayerBatchPlan s=sourcePlan();p.build(s,new int[]{0,288,576,864,-1},new int[]{288,288,288,144,0},new int[]{36,36,36,18,0},5);assertEquals(4,p.packetCount());p.clear();assertEquals(0,p.packetCount());assertEquals(0,p.batchCount());assertThrows(IllegalArgumentException.class,()->p.build(s,new int[5],new int[5],new int[5],4));assertThrows(IndexOutOfBoundsException.class,()->p.batchSize(0));}
}
